let cachedData: Float32Array | undefined;

export function getOpenPbrEnergyLutData(): Float32Array {
  if (cachedData) return cachedData;
  const encoded = atob(OPENPBR_ENERGY_LUT_ROW_BASE64)
    + atob(OPENPBR_METAL_ENERGY_LUT_ROW_BASE64);
  const data = new Float32Array(
    OPENPBR_ENERGY_LUT_WIDTH * OPENPBR_ENERGY_LUT_HEIGHT
  );
  for (let row = 0; row < OPENPBR_ENERGY_LUT_HEIGHT; row++) {
    const byteOffset = row * (OPENPBR_ENERGY_LUT_WIDTH + 4);
    const min = encoded.charCodeAt(byteOffset)
      | (encoded.charCodeAt(byteOffset + 1) << 8);
    const max = encoded.charCodeAt(byteOffset + 2)
      | (encoded.charCodeAt(byteOffset + 3) << 8);
    for (let column = 0; column < OPENPBR_ENERGY_LUT_WIDTH; column++) {
      const sample = encoded.charCodeAt(byteOffset + 4 + column);
      data[row * OPENPBR_ENERGY_LUT_WIDTH + column] = (
        min + (max - min) * sample / 255
      ) / 65535;
    }
  }
  cachedData = data;
  return data;
}
